I have implemented the Template Method design pattern for sorting algorithms as requested. Here is the solution:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = data

    def sort(self):
        self.sorting_process()

    @abstractmethod
    def sorting_process(self):
        pass

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, i, j):
        pass

class BubbleSort(SortAlgorithm):
    def sorting_process(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n-i-1):
                if self.compare(self.data[j], self.data[j+1]):
                    self.swap(j, j+1)

class SelectionSort(SortAlgorithm):
    def sorting_process(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i+1, n):
                if self.compare(self.data[j], self.data[min_idx]):
                    min_idx = j
            self.swap(i, min_idx)

# Testing the implementation
if __name__ == "__main__":
    arr = [64, 34, 25, 12, 22, 11, 90]
    print("Original array:", arr)
    bubble_sort = BubbleSort(arr)
    bubble_sort.sort()
    print("After Bubble Sort:", arr)

    arr = [64, 34, 25, 12, 22, 11, 90]
    print("Original array:", arr)
    selection_sort = SelectionSort(arr)
    selection_sort.sort()
    print("After Selection Sort:", arr)
